ee:message.ee:set-payload:
%dw 2.0
output application/json
var coleccion = if (isEmpty(payload[0].payload) and isEmpty(payload[1].payload)) "" else if (isEmpty(payload[0].payload)) "ORDER" else "PQR"
var result = if (isEmpty(payload[0].payload)) payload[1].payload[0] else payload[0].payload[0]
---
if (isBlank(coleccion)) 
{
  "status": 404,
  "code": "NOT_FOUND",
  "message": {
    "message": "There are no matching records"
  },
  "messageServer": "",
  "cause": [
    {
      "origin": "app.name",
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}
else if (coleccion == "ORDER")
{
    id: result.Numero_Orden,
    estado: {
        codigo: result.Estado_Orden_Comercial.Codigo,
        nombre: result.Estado_Orden_Comercial.Descripcion
    },
    "fecha-creacion": do {
        var date = result.Fecha_Creacion as DateTime
        ---
        {
            dia: date.day,
            franja: date.timezone,
            anio: date.year,
            mes: {
                numero: date.month,
                nombre: date as String {format: "MMMM"}
            },
            hora: date as String {format: "hh:mm:ss a"}
        }
    },
    "fecha-visita": do {
        var date = result.Agendamiento.Fecha_Agenda as DateTime
        ---
        {
            dia: date.day,
            franja: result.Agendamiento.Franja_Agenda,
            anio: date.year,
            mes: {
                numero: date.month,
                nombre: date as String {format: "MMMM"}
            },
            hora: date as String {format: "hh:mm:ss a"}
        }
    }
}
else
do {
    var ind = indexOf(result.agendas_tmr.oportunidad_agenda, max(result.agendas_tmr.oportunidad_agenda map ($ default "")))
    ---
    {
    id: result.order_number,
    estado: {
        codigo: result.agendas_tmr[ind],
        nombre: result.agendas_tmr[ind].estado_agenda
    },
    "fecha-creacion": do {
        var date = result.fecha_actualizacion as DateTime
        ---
        {
            dia: date.day,
            franja: date.timezone,
            anio: date.year,
            mes: {
                numero: date.month,
                nombre: date as String {format: "MMMM"}
            },
            hora: date as String {format: "hh:mm:ss a"}
        }
    },
    "fecha-visita": do {
        var date = result.agendas_tmr[ind].oportunidad_agenda as DateTime
        ---
        {
            dia: date.day,
            franja: result.agendas_tmr[ind].timeslot,
            anio: date.year,
            mes: {
                numero: date.month,
                nombre: date as String {format: "MMMM"}
            },
            hora: date as String {format: "hh:mm:ss a"}
        }
    }
    }
}
